import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        String s = scanner.next();

        // Map each digit to its prime factorization in terms of digits 2,3,5,7
        // We want to convert each digit's factorial into a product of digits (2,3,5,7)
        // such that the overall product is the same, and we want the maximum number.

        // For each digit d, d! can be expressed as a product of digits from {2,3,5,7}
        // We'll count the total number of each prime digit (2,3,5,7) in the factorization

        int count2 = 0, count3 = 0, count5 = 0, count7 = 0;

        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            int d = c - '0';
            // Factorize d! into digits 2,3,5,7
            // We need to find how many 2s, 3s, 5s, 7s multiply to d!
            // Actually, we can precompute for each digit 0-9 what digits (from 2,3,5,7) it contributes
            // 0! = 1 -> nothing
            // 1! = 1 -> nothing
            // 2! = 2 -> one 2
            // 3! = 6 = 2*3 -> one 2, one 3
            // 4! = 24 = 2*3*4 = 2*3*2*2 -> three 2s, one 3
            // 5! = 120 = 5! = 120 = 2^3 * 3 * 5 -> but we need to express as digits 2,3,5,7
            // Wait, the problem says F(x) is product of factorials of digits of x.
            // So if x has digits d1, d2, ..., dk, then F(x) = d1! * d2! * ... * dk!
            // We need F(x) = F(a)
            // And x should not contain 0 or 1, and should be maximum.

            // So for each digit d in a, we need to factorize d! into a product of digits from {2,3,5,7}
            // and count how many of each digit we get.

            // Let's precompute the factorization of d! into digits 2,3,5,7
            // d! = product of digits from {2,3,5,7}
            // We can do this by repeatedly dividing by 7, 5, 3, 2 (in that order to get larger digits first? No, we just need the count)
            // Actually, we want to express d! as a product of digits 2,3,5,7.
            // The optimal way to maximize the final number is to have as many 7s as possible, then 5s, then 3s, then 2s.
            // But we need to factorize d! into these digits.

            // Let's compute the factorization:
            int val = factorial(d);
            // Now factorize val into digits 2,3,5,7
            // We'll divide by 7 as much as possible, then 5, then 3, then 2
            // But wait, we need to be careful. The factorization into digits 2,3,5,7 is unique if we consider that each digit is a prime power? No, 2,3,5,7 are all prime.
            // So d! = 2^a * 3^b * 5^c * 7^d
            // And we want to represent this as a product of digits 2,3,5,7.
            // Each digit 2 contributes one factor of 2.
            // Each digit 3 contributes one factor of 3.
            // Each digit 5 contributes one factor of 5.
            // Each digit 7 contributes one factor of 7.
            // So the number of 2s in the result is a, number of 3s is b, number of 5s is c, number of 7s is d.

            // Let's compute the prime factorization of d!
            int temp = val;
            int a2 = 0, a3 = 0, a5 = 0, a7 = 0;
            while (temp % 7 == 0) { a7++; temp /= 7; }
            while (temp % 5 == 0) { a5++; temp /= 5; }
            while (temp % 3 == 0) { a3++; temp /= 3; }
            while (temp % 2 == 0) { a2++; temp /= 2; }

            count2 += a2;
            count3 += a3;
            count5 += a5;
            count7 += a7;
        }

        // Now, to maximize the number, we should output digits in descending order: 7, 5, 3, 2
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < count7; i++) sb.append('7');
        for (int i = 0; i < count5; i++) sb.append('5');
        for (int i = 0; i < count3; i++) sb.append('3');
        for (int i = 0; i < count2; i++) sb.append('2');

        System.out.println(sb.toString());
    }

    static int factorial(int n) {
        int result = 1;
        for (int i = 2; i <= n; i++) {
            result *= i;
        }
        return result;
    }
}
