        for (int d = 9; d >= 2; d--) {
            int[] fp = factPrime[d];
            int maxCount = Integer.MAX_VALUE;
            for (int j = 0; j < 4; j++) {
                if (fp[j] > 0) {
                    maxCount = Math.min(maxCount, total[j] / fp[j]);
                }
            }
            if (maxCount == Integer.MAX_VALUE) maxCount = 0;
            for (int i = 0; i < maxCount; i++) {
                result.append(d);
            }
            for (int j = 0; j < 4; j++) {
                total[j] -= maxCount * fp[j];
            }
        }

        System.out.println(result.toString());
    }
}
